<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>The Great Wave off Kanagawa — low poly 3D wallpaper</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#e8dfc8}
  #c{display:block;width:100%;height:100%}
  #cap{position:fixed;left:14px;bottom:10px;color:#23415e;font:12px/1.4 Georgia,serif;
       letter-spacing:.06em;opacity:.85;pointer-events:none}
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="cap">The Great Wave off Kanagawa &middot; after Katsushika Hokusai (public domain) &middot; low-poly rebuild</div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

/* ---- palette taken from the print ---- */
const COL = {
  skyTop:   0xf2ead2,  // aged paper cream
  skyBot:   0xd9cfb2,
  paper:    0xefe6cc,
  prussian: 0x1f4e79,  // deep Prussian blue of the wave body
  prussian2:0x2e6da4,  // lighter blue of troughs
  foam:     0xf7f3e6,  // white foam
  foamShade:0xd8e4e8,
  hull:     0xc98f5a,  // tan hull
  hullDark: 0x8a5a33,
  sail:     0xe9dfc2,
  fuji:     0x4a6f92,  // blue-grey mountain
  fujiSnow: 0xf5f1e4,
  ink:      0x2b3a4a
};

const renderer = new THREE.WebGLRenderer({canvas:document.getElementById('c'),antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;

const scene = new THREE.Scene();
scene.background = new THREE.Color(COL.paper);
scene.fog = new THREE.Fog(COL.paper, 60, 160);

const camera = new THREE.PerspectiveCamera(42, innerWidth/innerHeight, .1, 400);
camera.position.set(0, 7.5, 46);
camera.lookAt(0, 6, 0);

/* flat, print-like lighting */
scene.add(new THREE.HemisphereLight(0xfff6dd, 0x33506b, 1.15));
const sun = new THREE.DirectionalLight(0xfff2d0, .55);
sun.position.set(-18, 30, 20);
scene.add(sun);

const flat = (color, opts={}) =>
  new THREE.MeshLambertMaterial({color, flatShading:true, ...opts});
// unlit material: foam and snow stay their print color regardless of light
const unlit = (color) =>
  new THREE.MeshBasicMaterial({color, flatShading:true});

/* =========================================================
   Sky: a big gradient plane behind everything (paper tone)
   ========================================================= */
{
  const g = new THREE.BufferGeometry();
  const v = new Float32Array([-80,-10,0,  80,-10,0,  80,40,0,  -80,40,0]);
  const c = [COL.skyBot,COL.skyBot,COL.skyTop,COL.skyTop].map(h=>new THREE.Color(h));
  const cc = new Float32Array(12);
  c.forEach((col,i)=>{cc[i*3]=col.r;cc[i*3+1]=col.g;cc[i*3+2]=col.b;});
  g.setAttribute('position', new THREE.BufferAttribute(v,3));
  g.setAttribute('color', new THREE.BufferAttribute(cc,3));
  g.setIndex([0,1,2, 0,2,3]);
  g.computeVertexNormals();
  const sky = new THREE.Mesh(g, new THREE.MeshBasicMaterial({vertexColors:true, side:THREE.DoubleSide}));
  sky.position.z = -90;
  scene.add(sky);
}

/* =========================================================
   Mount Fuji — low-poly cone with snow cap, centre-back
   ========================================================= */
const fuji = new THREE.Group();
{
  const body = new THREE.Mesh(new THREE.ConeGeometry(16, 14, 7, 3), flat(COL.fuji));
  body.position.y = 7;
  fuji.add(body);
  const cap = new THREE.Mesh(new THREE.ConeGeometry(6.2, 5.2, 7, 2), unlit(COL.fujiSnow));
  cap.position.y = 11.4;
  fuji.add(cap);
  // jagged snow line: a few small white shards on the shoulder
  for(let i=0;i<5;i++){
    const a = i/5*Math.PI*2 + .4;
    const s = new THREE.Mesh(new THREE.TetrahedronGeometry(1.6), unlit(COL.fujiSnow));
    s.position.set(Math.cos(a)*4.6, 9.6, Math.sin(a)*4.6);
    s.rotation.set(Math.random(),Math.random(),Math.random());
    fuji.add(s);
  }
}
fuji.position.set(7, -5.5, -46);
fuji.scale.setScalar(0.85);
scene.add(fuji);

